const labels={title:['上城驾飞挑战','Upper City drive–flight challenge'],intro:['沿实际道路驾车到起点，轮胎驾驶 → 指定区起飞 → 正向穿门 → 在现有 8 m 台地落稳。全程由你操纵；导航和挑战不会传送或补气。','Drive along real roads to the start, drive on wheels, take off inside the strip, cross the gate forward and settle on the existing 8 m terrace. You remain the pilot; navigation and the task never teleport or refill.'],navigate:['导航到起点','Route to start'],start:['开始 / 重试','Start / retry'],cancel:['取消 / 结束计时并接管','Cancel / end timing and take over'],preview:['显示挑战区域与门','Show task zones and gate'],supply:['本次供气预览（开始时应用，不补气）','Attempt supply preview (applied at start; no refill)'],bench:['恒压外供气 · 单独成绩组','External constant pressure · separate class'],finite:['有限车载气源 · 单独成绩组','Finite onboard gas · separate class'],rules:['固定规则与操作','Frozen rules and controls'],records:['历史与本会话结果','Saved and session results'],export:['导出完整整库 JSON','Export complete library JSON'],one:['导出选中完整结果','Export selected complete result'],protected:['导出受保护旧原文','Export protected original'],import:['合并导入 JSON','Merge JSON archive'],events:['关键事件回看（现场不移动）','Event review (live vehicle unchanged)'],details:['专业指标与证据身份','Metrics and evidence identity'],hide:['隐藏结果提示','Hide result prompt']};
const reasons={recording_started:['已取消：开始独立现场记录','Cancelled: separate live recording started'],research_control:['已取消：研究控制接管','Cancelled: research control took over'],inspection_open:['已取消：打开车辆检视','Cancelled: vehicle inspection opened'],graphics_context_lost:['已取消：三维图形上下文中断','Cancelled: graphics context lost'],start_failed:['开始条件未满足；原设置已恢复','Start failed; prior settings restored'],drive_to_start:['请先沿道路驶到起点中心 2.5 m 内。','Drive within 2.5 m of the start.'],start_support:['起点须至少三轮接触上城台地。','At least three wheels must contact the Upper City terrace.'],stop_first:['先停车并落稳。','Stop and settle first.'],face_forward:['车头须朝 +Z（地图北向），偏差不超过 20°。','Face +Z (map north), within 20°.'],drive_mode_required:['切回 DRIVE 并保持接地水平。','Select DRIVE and remain level on the road.'],supply_mismatch:['所选供气与当前物理模式不一致。','Selected supply does not match the physical mode.'],city_required:['请先返回城市。','Return to the city first.'],platform_identity_changed:['当前平台碰撞几何与任务不同，拒绝开始。','Platform collision geometry differs; start refused.'],stable_platform_landing:['完成：无违规穿门并在平台落稳','Completed: gate passed and stable platform landing'],missed_takeoff_strip:['失败：驶离指定起飞区而未起飞','Failed: left the takeoff strip without taking off'],takeoff_before_drive_checkpoint:['失败：未完成地面驾驶就起飞','Failed: took off before the drive checkpoint'],left_drive_lane:['失败：地面阶段驶离指定车道','Failed: left the designated drive lane'],invalid_drive_checkpoint:['失败：驾驶检查点缺少连续轮胎行驶','Failed: drive checkpoint lacks wheel driving'],gate_envelope_outside:['失败：穿门时车辆包络超出门框','Failed: physical vehicle envelope missed the gate opening'],reverse_gate_crossing:['失败：反向穿门','Failed: reverse gate crossing'],gate_not_airborne:['失败：未完全离地穿门','Failed: gate crossed without full takeoff'],gate_forward_speed:['失败：未达到正向穿门速度','Failed: insufficient forward gate speed'],contact_before_gate:['失败：穿门前重新接地','Failed: contact before the gate'],landing_outside_platform_zone:['失败：落在指定平台区域外','Failed: landed outside the platform zone'],hard_or_tilted_landing:['失败：硬着陆或触地姿态超限','Failed: hard or tilted landing'],hull_collision:['失败：车体碰撞','Failed: hull collision'],outside_task_bounds:['失败：超出声明任务区域','Failed: outside the task bounds'],conditions_changed:['失败：途中修改了冻结条件','Failed: frozen conditions changed'],reset_attempt:['失败：中途复位；已保留复位前末态','Failed: reset attempted; pre-reset terminal retained'],physical_discontinuity:['失败：物理状态不连续','Failed: physical-state discontinuity'],fixed_step_discontinuity:['失败：物理时间或步号不连续','Failed: physical time/step discontinuity'],fixed_step_protocol:['失败：固定 120 Hz 接线异常','Failed: 120 Hz integration contract violated'],unacknowledged_fixed_step:['失败：上一步尚未确认积分','Failed: preceding fixed step not acknowledged'],non_finite_state:['失败：非有限状态，故障证据已保留','Failed: non-finite state; evidence retained'],solver_fault:['失败：求解器故障，触发态已保留','Failed: solver fault; trigger retained'],task_timeout:['失败：75 s 内未完成','Failed: not completed within 75 s'],pilot_takeover:['已取消，驾驶控制保留','Cancelled; pilot control retained'],pilot_cancel:['已取消，驾驶控制保留','Cancelled; pilot control retained'],context_change:['已取消：切换场景','Cancelled: context changed'],record_terminal_failure:['失败：末态记录不完整','Failed: terminal capture unavailable']};
