const phaseText=phase=>({ready:['准备','Ready'],drive:['轮胎驾驶至黄色起飞区','Drive on wheels to the yellow strip'],takeoff:['在黄色区域起飞 · H 后按 E','Take off inside yellow strip · H, then E'],gate:['完全离地，沿 +Z 穿过青色门','Fully airborne, cross cyan gate along +Z'],landing:['在绿色区域减速并落稳 · L 自动着陆','Slow down over green area and settle · L to land'],completed:['完成','Completed'],failed:['失败','Failed'],cancelled:['已取消','Cancelled'],timeout:['超时','Timeout']})[phase]?.[getLanguage()==='en'?1:0]??phase;

function createTaskMarkers(scene){
 const root=new THREE.Group();root.name='City flight task / virtual cues, no collision geometry';root.visible=false;scene?.add(root);
 const materials=[],geometries=[];
 function line(points,color){const geometry=new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(...p))),material=new THREE.LineBasicMaterial({color,transparent:true,opacity:.9,depthTest:true,depthWrite:false});geometries.push(geometry);materials.push(material);const object=new THREE.Line(geometry,material);root.add(object);return object;}
 function rectangle(bounds,y,color){line([[bounds.minX,y,bounds.minZ],[bounds.maxX,y,bounds.minZ],[bounds.maxX,y,bounds.maxZ],[bounds.minX,y,bounds.maxZ],[bounds.minX,y,bounds.minZ]],color);}
 const start=CITY_FLIGHT_ROUTE.start,landing=CITY_FLIGHT_ROUTE.landing,gate=CITY_FLIGHT_ROUTE.gate;
 for(const [center,radius,color]of [[start.center,start.radiusM,0xdcebc0],[landing.center,landing.radiusM,0xa0edbb]]){const points=[];for(let i=0;i<=72;i++){const a=i/72*Math.PI*2;points.push([center[0]+Math.cos(a)*radius,8.035,center[2]+Math.sin(a)*radius]);}line(points,color);}
 rectangle(CITY_FLIGHT_ROUTE.takeoff,8.035,0xeac481);rectangle(landing.bounds,8.036,0xa0edbb);
 for(const z of [234,242,250])line([[398.8,8.04,z],[400,8.04,z+2],[401.2,8.04,z]],0xe0edcb);
 const gateRoot=new THREE.Group();gateRoot.name='Gate 1 / +Z / exact frozen aperture';root.add(gateRoot);
 function bar(size,position){const geometry=new THREE.BoxGeometry(...size),material=new THREE.MeshBasicMaterial({color:0x8ce9e1,transparent:true,opacity:.82,depthTest:true,depthWrite:false});geometries.push(geometry);materials.push(material);const mesh=new THREE.Mesh(geometry,material);mesh.position.set(...position);gateRoot.add(mesh);}
 const [x,y,z]=gate.center;bar([.08,gate.halfHeightM*2,.08],[x-gate.halfWidthM,y,z]);bar([.08,gate.halfHeightM*2,.08],[x+gate.halfWidthM,y,z]);bar([gate.halfWidthM*2,.08,.08],[x,y-gate.halfHeightM,z]);bar([gate.halfWidthM*2,.08,.08],[x,y+gate.halfHeightM,z]);
 line([[x-1,8.04,z-3],[x,8.04,z-1],[x+1,8.04,z-3]],0x8ce9e1);
 return{root,update(visible,state){root.visible=visible;for(const child of gateRoot.children)child.material.color.setHex(state?.gatePassed?0xa0edbb:0x8ce9e1);},dispose(){scene?.remove(root);geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());}};
}
export function createCityFlightUI({mount,hudMount,scene,getSim,getContext=()=> 'city',onNavigate=()=>{},onBeforeStart=()=>{},onStart=()=>{},onFinish=()=>{},notify=()=>{},storage}={}){
 if(!mount||!getSim)throw Error('City task UI needs mount and getSim');
 const doc=mount.ownerDocument,loaded=loadCityFlightLibrary(storage),persistence=new PersistenceState(loaded.warning??'',loaded.protectedRaw),markers=createTaskMarkers(scene);
 let library=loaded.value,diskRaw=loaded.raw,runner=null,selectedId=library.records.at(-1)?.id??null,message='',showResult=true,disposed=false,taskReturnSettings=null,scopedSim=null,exitContract=null;
 const panel=doc.createElement('section');panel.className='rc-section city-flight-panel';panel.setAttribute('data-no-i18n','');panel.innerHTML='<h3 data-cf-label="title"></h3><p class="field-help" data-cf-label="intro"></p><p data-cf="persistence" role="alert" hidden></p><div class="city-flight-actions"><button type="button" data-cf-action="navigate" data-cf-label="navigate"></button><button type="button" data-cf-action="start" data-cf-label="start"></button><button type="button" data-cf-action="cancel" data-cf-label="cancel"></button></div><label class="rc-field"><span data-cf-label="supply"></span><select data-cf="supply"><option value="bench" data-cf-label="bench"></option><option value="finite" data-cf-label="finite"></option></select></label><label><input type="checkbox" data-cf="preview"> <span data-cf-label="preview"></span></label><p data-cf="state" role="status"></p><p class="field-help" data-cf="eligibility"></p><details><summary data-cf-label="rules"></summary><p class="field-help" data-cf="rules"></p></details><label class="rc-field"><span data-cf-label="records"></span><select data-cf="records"></select></label><p data-cf="verdict"></p><div class="city-flight-actions"><button type="button" data-cf-action="export" data-cf-label="export"></button><button type="button" data-cf-action="one" data-cf-label="one"></button><button type="button" data-cf-action="protected" data-cf-label="protected" hidden></button><label class="secondary-button"><span data-cf-label="import"></span><input type="file" accept="application/json,.json" data-cf="import"></label></div><details><summary data-cf-label="details"></summary><pre data-cf="metrics"></pre><label class="rc-field"><span data-cf-label="events"></span><select data-cf="events"></select></label><pre data-cf="event"></pre></details>';
 mount.append(panel);const $=key=>panel.querySelector('[data-cf="'+key+'"]');$('supply').value=getSim().params.supplyMode;
 const hud=doc.createElement('aside');hud.className='city-flight-status';hud.setAttribute('data-no-i18n','');hud.setAttribute('aria-live','polite');hud.innerHTML='<strong></strong><p></p><button type="button"></button>';hud.hidden=true;(hudMount??doc.getElementById('app')??mount).append(hud);hud.querySelector('button').onclick=()=>{if(runner&&!runner.finished)cancel('pilot_cancel');else{showResult=false;paintStatus();}};
 const style=doc.createElement('style');style.textContent='.city-flight-panel{margin-top:22px;padding-top:18px;border-top:1px solid #63797466}.city-flight-panel p{line-height:1.65}.city-flight-panel pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto;font-size:11px}.city-flight-actions{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}.city-flight-panel [data-cf="persistence"]{color:#f2c48a;border-left:3px solid #caa16b;padding:8px}.city-flight-panel select{max-width:100%}.city-flight-panel input[type=file]{max-width:180px;display:block}.city-flight-status{position:absolute;right:22px;top:104px;max-width:330px;padding:13px 16px;border:1px solid #9ccbbb66;border-radius:8px;background:#102323e8;color:#dfefdf;z-index:24;font-size:12px;pointer-events:auto}.city-flight-status p{margin:6px 0;line-height:1.6}.city-flight-status button{font-size:11px;padding:5px 8px}.city-flight-status[hidden]{display:none}@media(max-width:700px){.city-flight-status{right:10px;top:86px;max-width:230px;padding:9px;font-size:11px}}';panel.append(style);
 function selected(){return library.records.find(r=>r.id===selectedId)??null;}
 function download(value,name,raw=false){const blob=new Blob([raw?value:JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=doc.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
 function save(ids=[]){try{saveCityFlightLibrary(storage,library,{protectedRaw:loaded.protectedRaw,expectedRaw:diskRaw});diskRaw=storage.getItem(CITY_FLIGHT_LIBRARY_KEY);persistence.saved();}catch(error){persistence.failed(error,ids);}paintStatus();}
 function restoreSettings(reason){if(!taskReturnSettings)return;const settings=taskReturnSettings,sim=scopedSim;taskReturnSettings=null;scopedSim=null;try{exitContract=restoreTaskSettings(sim,settings,{reason});}catch(error){exitContract={reason,restored:false,physicalStateUnchanged:null,error:String(error.message),authority:'pilot'};message=L('任务末态已保留，但设置恢复失败：','Task terminal retained, but settings restoration failed: ')+error.message;notify(message,'warning');}return exitContract;}
 function accept(result){
  const restored=restoreSettings(result.reason);if(restored)result.exitContract=copy(restored);
  validateCityFlightResult(result);library={...library,records:[...library.records,result]};selectedId=result.id;showResult=true;save([result.id]);message=reasonText(result.reason);render();notify(message,result.status==='completed'?'info':'warning');onFinish(result);
 }
 function start(){
  if(runner&&!runner.finished)throw Error(L('请先结束当前挑战。','Finish the current attempt first.'));
  if(getContext()!=='city')throw Error(reasonText('city_required'));
  const sim=getSim(),task=makeCityFlightTask({supplyMode:$('supply').value});
  // Refusing an invalid initial state must not cancel an existing controller
  // or pass through the task-exit helper, which deliberately hands off to pilot.
  // Supply mismatch alone is expected: the selector is still only a preview.
  const initialCheck=cityFlightStartCheck(sim,{task}),initialIssues=initialCheck.issues.filter(reason=>reason!=='supply_mismatch');
  if(initialIssues.length)throw Error(initialIssues.map(reasonText).join(' '));
  onBeforeStart();taskReturnSettings=captureTaskSettings(sim);scopedSim=sim;exitContract=null;
  try{sim.setSupplyMode(task.supplyMode);const check=cityFlightStartCheck(sim,{task});if(!check.ok)throw Error(check.issues.map(reasonText).join(' '));runner=new CityFlightChallenge(sim,{task,onFinish:accept});runner.start();$('preview').checked=true;showResult=true;message='';onStart();paintStatus();return runner;}catch(error){if(runner&&!runner.finished&&runner.started)runner.cancel('start_failed');else restoreSettings('start_failed');throw error;}
 }
 function cancel(reason='pilot_takeover'){if(runner&&!runner.finished)return runner.cancel(reason);return null;}
 function showEvent(index){const r=selected(),event=r?.events[index];if(!event){$('event').textContent='';return;}const samples=r.liveExperiment.samples,nearest=samples.reduce((best,s)=>!best||Math.abs(s.step-event.step)<Math.abs(best.step-event.step)?s:best,null);$('event').textContent=JSON.stringify({event,nearestStored20HzSample:nearest,samplingNote:L('事件与规则判定为120 Hz；此相邻显示样本为20 Hz，不移动现场。完整输入与命令在导出中。','Events and decisions use 120 Hz; this nearby display sample is 20 Hz. Live vehicle unchanged; full inputs and commands are exported.')},null,2);}
 function render(){
  for(const element of panel.querySelectorAll('[data-cf-label]'))element.textContent=labels[element.dataset.cfLabel]?.[getLanguage()==='en'?1:0]??element.dataset.cfLabel;
  $('rules').textContent=L('起点：(400, 8 m 路面, 230)，朝 +Z；先驾驶至少18 m并越过z252，再在z252–266区内用H/E起飞。青色门位于z280，世界高度9.3–14.7 m、宽11 m，必须正向、完全离地且全车包络在门内。绿色着陆区中心(400,8,305)，半径4.5 m。首次接地垂速≤1.4 m/s、倾角≤8°；至少三轮接触实际台地、水平≤0.4 m/s、垂直≤0.35 m/s、角速度≤0.15 rad/s并保持0.5 s。75 s超时；途中车体碰撞、复位、补气、改风/故障/物理参数判失败。L为既有自动着陆；导航与挑战本身不代驾。有限供气使用当前余气，外供气成绩单独统计。风、喷口故障和其他模型参数继承当前城市并在开始时冻结；供气选择只是预览。结束、取消或失败先保存末态，再恢复开始前的设置；不恢复体态、不补气。','Start: (400, road Y=8 m, 230), facing +Z. Drive at least 18 m past z252, then use H/E to take off inside z252–266. The cyan gate at z280 spans world Y9.3–14.7 m and is 11 m wide: cross forward, fully airborne, with the whole physical envelope inside. Land at (400,8,305), radius 4.5 m. First contact: descent <=1.4 m/s, tilt <=8°. At least three wheels on the real terrace, horizontal <=0.4 m/s, vertical <=0.35 m/s and angular rate <=0.15 rad/s for 0.5 s. Timeout 75 s. Hull collision, reset, refill or altered wind/fault/model settings fail. L uses the existing landing aid; navigation and the task do not drive for you. Finite mode uses current gas; external supply has a separate record class. Wind, nozzle faults and other model settings are inherited from the city and frozen at start. Supply selection is a preview. Completion, cancellation or failure saves the terminal first, then restores pre-task settings without restoring pose or refilling.');
  const oldEvent=$('events').value;$('records').replaceChildren();for(const record of [...library.records].reverse()){const option=doc.createElement('option');option.value=record.id;option.textContent=(record.supplyMode==='bench'?'BENCH':'FINITE')+' · '+phaseText(record.status)+' · '+fmt(record.durationS)+' s · '+record.id;$('records').append(option);}if(selectedId)$('records').value=selectedId;
  const r=selected();if(r){const best=bestCityFlight(library.records,r.task,r.conditionsLabel);$('verdict').textContent=reasonText(r.reason)+(best?' · '+L('同条件个人最好 ','Same-conditions personal best ')+fmt(best.durationS)+' s':'');$('metrics').textContent=JSON.stringify({identity:r.identity,taskId:r.taskId,conditionsLabel:r.conditionsLabel,collisionIdentity:r.collisionIdentity,supplyMode:r.supplyMode,status:r.status,reason:r.reason,summary:r.summary,liveExperimentId:r.liveExperimentId,sampling:r.sampling,exitContract:r.exitContract??null},null,2);$('events').replaceChildren();r.events.forEach((event,i)=>{const option=doc.createElement('option');option.value=i;option.textContent=fmt(event.timeS,3)+' s · '+event.type;$('events').append(option);});$('events').value=oldEvent!==''&&Number(oldEvent)<r.events.length?oldEvent:String(r.events.length-1);showEvent(Number($('events').value));}else{$('verdict').textContent=L('尚无结果；失败和取消也保留完整记录。','No results yet. Failed and cancelled attempts also retain complete records.');$('metrics').textContent='';$('events').replaceChildren();$('event').textContent='';}
  paintStatus();
 }
 function paintStatus(){
  if(disposed)return;const state=runner?.getState(),active=state?.running,city=getContext()==='city',sim=getSim();const persisted=persistence.snapshot();$('persistence').hidden=!persisted.sessionOnly;$('persistence').textContent=persisted.sessionOnly?L('仅本会话 / 未保存：','Session only / unsaved: ')+persisted.message+L(' 当前完整结果与整库仍可导出；旧档未清空。',' Complete results and library remain exportable; old data was not cleared.'):'';
  panel.querySelector('[data-cf-action="protected"]').hidden=loaded.protectedRaw===null;$('supply').disabled=!!active;panel.querySelector('[data-cf-action="start"]').disabled=!!active;panel.querySelector('[data-cf-action="cancel"]').disabled=!active;
  $('state').textContent=active?phaseText(state.phase)+' · '+fmt(state.timeS,1)+' s · '+(state.supplyMode==='bench'?'BENCH':'FINITE')+' · '+L('控制：驾驶者','Control: pilot'):message||L('导航到起点后停车，预览规则再开始。','Route to the start, stop, review the rules, then start.');
  if(!active&&city){const check=cityFlightStartCheck(sim,{task:makeCityFlightTask({supplyMode:$('supply').value})}),issues=check.issues.filter(reason=>reason!=='supply_mismatch');$('eligibility').textContent=!issues.length?L('起点条件满足；开始会应用所选供气，体态与当前剩气保持。','Start conditions met; selected supply will be applied without moving or refilling.') : issues.map(reasonText).join(' ');}else $('eligibility').textContent=city?'':reasonText('city_required');
  markers.update(city&&($('preview').checked||active),state);hud.hidden=!city||(!active&&(!showResult||!runner?.result));
  hud.querySelector('strong').textContent=active?phaseText(state.phase):reasonText(runner?.result?.reason??'');hud.querySelector('p').textContent=active?fmt(state.timeS,1)+' / 75 s · '+(state.supplyMode==='bench'?L('恒压外供气','External supply'):L('有限余气 ','Finite gas ')+fmt(sim.gasMass,0)+' kg')+'\n'+L('控制：驾驶者 · H/E起飞 · W/S移动 · L落地','Pilot controls · H/E lift · W/S move · L land')+'\n'+L('风 / 故障继承城市并冻结','Wind / faults inherited and frozen')+(state.phase==='landing'?'\n'+L('落稳 ','Stable ')+fmt(state.stableSeconds,2)+' / 0.50 s':''):(persisted.sessionOnly?L('仅本会话 / 未保存；请导出。','Session only / unsaved; export available.'):L('完整记录已保存，可在地图回看和导出。','Complete record saved; review and export in the map.')+(exitContract?.restored===false?L('设置恢复失败，请查看详情。','Settings restoration failed; see details.'):exitContract?L('原设置已恢复，实际末态与剩气保留。','Prior settings restored; actual terminal and gas retained.'):''));hud.querySelector('button').textContent=active?labels.cancel[getLanguage()==='en'?1:0]:labels.hide[getLanguage()==='en'?1:0];
  panel.dataset.cityFlight=JSON.stringify({running:!!active,phase:state?.phase??'ready',recordCount:library.records.length,selectedId,persistence:persisted,taskId:state?.taskId??null});
 }
 panel.addEventListener('click',event=>{const button=event.target.closest('[data-cf-action]');if(!button)return;event.stopPropagation();try{const action=button.dataset.cfAction;if(action==='navigate'){$('preview').checked=true;onNavigate('city-challenge-start');message=L('已规划到真实车行起点；返回驾驶后沿路线前往。','Route planned to the real start; return to driving and follow it.');}else if(action==='start')start();else if(action==='cancel')cancel('pilot_cancel');else if(action==='export')download({...library,persistence:persistence.snapshot(),protectedRaw:loaded.protectedRaw},'roadster-city-flight-library.json');else if(action==='one'&&selected())download(selected(),selectedId+'.json');else if(action==='protected'&&loaded.protectedRaw!==null)download(loaded.protectedRaw,'roadster-city-flight-protected-raw.json',true);}catch(error){message=error.message;notify(message,'warning');}paintStatus();});
 panel.addEventListener('change',event=>{try{if(event.target===$('supply')){if(runner&&!runner.finished)throw Error('Attempt running');if(getContext()!=='city')throw Error(reasonText('city_required'));message=L('供气选择仅为本次任务预览；开始时应用，结束后恢复原设置。','Supply is a preview for this attempt; applied at start and prior settings restored on exit.');}else if(event.target===$('records')){selectedId=event.target.value;render();}else if(event.target===$('events'))showEvent(Number(event.target.value));}catch(error){message=error.message;}paintStatus();});
 $('import').addEventListener('change',async event=>{try{const file=event.target.files?.[0];if(!file)return;if(file.size>12*1024*1024)throw Error('Import exceeds 12 MiB');const incoming=parseCityFlightArchive(await file.text()),merged=new Map(library.records.map(r=>[r.id,r]));for(const record of incoming.records){const old=merged.get(record.id);if(old&&contentLabel(old)!==contentLabel(record))throw Error('Record ID conflict; existing record unchanged');merged.set(record.id,record);}library={...library,records:[...merged.values()]};selectedId=incoming.records.at(-1)?.id??selectedId;save(incoming.records.map(r=>r.id));message=L('归档已合并；保存状态独立显示。','Archive merged; storage state is shown separately.');render();}catch(error){message=error.message;paintStatus();}finally{event.target.value='';}});
 const offLanguage=onLanguageChange(render);render();
 return{panel,hud,start,cancel,beforeStep(input={}){if(runner&&!runner.finished){if(runner.sim!==getSim()||getContext()!=='city'){cancel('context_change');return input;}return runner.beforeStep(input);}return input;},afterStep(t,input,dt){if(runner&&!runner.finished)runner.afterStep(t,input,dt);},update:paintStatus,needsFixedStep:()=>!!runner&&!runner.finished,onContextChange(){if(runner&&!runner.finished)cancel('context_change');paintStatus();},getState:()=>({running:!!runner&&!runner.finished,recordCount:library.records.length,selectedId,persistence:persistence.snapshot(),live:runner?.getState()??null,exitContract:copy(exitContract)}),getRecords:()=>copy(library.records),dispose(){if(disposed)return;cancel('pilot_cancel');disposed=true;offLanguage();markers.dispose();panel.remove();hud.remove();}};
}
